export const WORDS = SETS.flatMap(s => s.words);

// O(1) 초고속 조회 Map
const wordMap = new Map(WORDS.map(w => [w.id, w]));

export const wordById = (id) => wordMap.get(id);

export const getSetsByMajor = (majorId) => SETS.filter(s => s.majorId === majorId);

export const getWordsByMajor = (majorId) => WORDS.filter(w => w.majorId === majorId);

export const getMajorById = (majorId) => MAJORS.find(m => m.id === majorId);
